// src/components/HomePage.js
import React from 'react';
import { Link } from 'react-router-dom';

const HomePage = ({ isAuthenticated }) => {
  return (
    <div className="home-page">
      {/* Home Section */}
      <section id="home" className="section home-section">
        <h1>Welcome to Real Time Human Detection System</h1>
        <p>
          Our innovative solution uses real-time detection to monitor human presence.
        </p>
        <Link to={isAuthenticated ? "/dashboard" : "/signin"} className="get-started-button">
          Get Started
        </Link>
      </section>

      {/* About Section */}
      <section id="about" className="section about-section">
        <h2>About</h2>
        <p>
          This system leverages advanced technology to provide real-time human detection in various scenarios.
        </p>
      </section>

      {/* Features Section */}
      <section id="features" className="section features-section">
        <h2>Features</h2>
        <ul>
          <li>Real-time monitoring</li>
          <li>High accuracy detection</li>
          <li>Easy integration</li>
          <li>Customizable notifications</li>
        </ul>
      </section>

      {/* Contact Section */}
      <section id="contact" className="section contact-section">
        <h2>Contact Us</h2>
        <p>
          Have questions? Reach out to our team at <a href="mailto:support@example.com">support@example.com</a>.
        </p>
      </section>

      {/* Footer */}
      <footer className="footer">
        <p>© 2025 RealTimeHumanDetect. All rights reserved.</p>
      </footer>
    </div>
  );
};

export default HomePage;
